def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {name: {row["version"]: row for row in packages[name]} for name in names}
        choices = [[-1] + sorted(rows[name]) for name in names]
        best_vector = None
        best = None

        def check(vector):
            installed = {name: vector[i] for i, name in enumerate(names)
                         if vector[i] != -1}
            for name, bounds in roots.items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    return False
            for name, version in installed.items():
                if version in blocked.get(name, ()):
                    return False
                if name in pins and pins[name] != version:
                    return False

            edges = {name: [] for name in installed}
            for name, version in installed.items():
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = installed.get(dep["name"])
                    if target is None or not dep["min"] <= target <= dep["max"]:
                        return False
                    edges[name].append(dep["name"])

            # Every installed package must be reachable from a root.
            reached = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reached:
                    continue
                reached.add(name)
                if name in edges:
                    stack.extend(edges[name])
            if reached != set(installed):
                return False

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            return all(visit(name) for name in edges)

        def search(i, vector):
            nonlocal best_vector, best
            if i == len(names):
                if check(vector) and (best_vector is None or tuple(vector) > best_vector):
                    best_vector = tuple(vector)
                    best = {name: version for name, version in zip(names, vector)
                            if version != -1}
                return
            for version in choices[i]:
                vector.append(version)
                search(i + 1, vector)
                vector.pop()

        search(0, [])
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in data["jobs"] if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for group in combinations(options, k):
            ids = {job["id"] for job in group}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in group:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(name, 0) <= high
                   for name, (low, high) in quotas.items()):
                continue
            ordered = sorted(group, key=lambda job: (job["start"], job["end"], job["id"]))
            active = []
            feasible = True
            for job in ordered:
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > 2:
                    feasible = False
                    break
            if not feasible:
                continue
            chosen_ids = sorted(ids)
            value = sum(job["value"] for job in group)
            if (best_value is None or value > best_value or
                    (value == best_value and chosen_ids < best_ids)):
                best_value, best_ids = value, chosen_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        start_node = data["source"]
        start_time = data["start"]
        initial_mask = bit.get(start_node, 0)
        initial = (start_node, initial_mask, data["coupons"])
        distances = {initial: start_time}
        queue = [(start_time, start_node, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, left = heapq.heappop(queue)
            state = (node, mask, left)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                v = edge["v"]
                next_mask = mask | bit.get(v, 0)
                durations = [(edge["duration"], left)]
                if left:
                    durations.append((max(2, edge["duration"] - edge.get("discount", 0)), left - 1))
                for duration, next_left in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (v, next_mask, next_left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, v, next_mask, next_left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
